  #define AXONS_AXONDSP_CFGDESCCMDTYPERB_CFGCMD_OPMAR (0x02UL) /*!< (unspecified)                                              */
  #define AXONS_AXONDSP_CFGDESCCMDTYPERB_CFGCMD_OPFIR (0x03UL) /*!< (unspecified)                                              */
  #define AXONS_AXONDSP_CFGDESCCMDTYPERB_CFGCMD_OPFIRX (0x04UL) /*!< (unspecified)                                             */
  #define AXONS_AXONDSP_CFGDESCCMDTYPERB_CFGCMD_OPNORM (0x05UL) /*!< (unspecified)                                             */
  #define AXONS_AXONDSP_CFGDESCCMDTYPERB_CFGCMD_OPAXPBY (0x06UL) /*!< (unspecified)                                            */
  #define AXONS_AXONDSP_CFGDESCCMDTYPERB_CFGCMD_OPACC (0x08UL) /*!< (unspecified)                                              */
  #define AXONS_AXONDSP_CFGDESCCMDTYPERB_CFGCMD_OPXPY (0x09UL) /*!< (unspecified)                                              */
  #define AXONS_AXONDSP_CFGDESCCMDTYPERB_CFGCMD_OPXMY (0x0AUL) /*!< (unspecified)                                              */
  #define AXONS_AXONDSP_CFGDESCCMDTYPERB_CFGCMD_OPAXPB (0x0BUL) /*!< (unspecified)                                             */
