  #define AXONS_AXONDSP_CFGCORECTRL_CFGMAXAHBBURST_NONE (0x0UL) /*!< (unspecified)                                             */
  #define AXONS_AXONDSP_CFGCORECTRL_CFGMAXAHBBURST_FOURBEATS (0x1UL) /*!< (unspecified)                                        */
