  #define ETB_PERIPHID1_PART_1_Pos (0UL)             /*!< Position of PART_1 field.                                            */
  #define ETB_PERIPHID1_PART_1_Msk (0xFUL << ETB_PERIPHID1_PART_1_Pos) /*!< Bit mask of PART_1 field.                          */

