  #define ETB_PERIPHID3_REVAND_Pos (4UL)             /*!< Position of REVAND field.                                            */
  #define ETB_PERIPHID3_REVAND_Msk (0xFUL << ETB_PERIPHID3_REVAND_Pos) /*!< Bit mask of REVAND field.                          */


