  #define ETB_COMPID1_PRMBL_1_Pos (0UL)              /*!< Position of PRMBL_1 field.                                           */
  #define ETB_COMPID1_PRMBL_1_Msk (0xFUL << ETB_COMPID1_PRMBL_1_Pos) /*!< Bit mask of PRMBL_1 field.                           */

