  #define ETM_TRCCONFIGR_LOADASP0INST_Min (0x0UL)    /*!< Min enumerator value of LOADASP0INST field.                          */
  #define ETM_TRCCONFIGR_LOADASP0INST_Max (0x1UL)    /*!< Max enumerator value of LOADASP0INST field.                          */
  #define ETM_TRCCONFIGR_LOADASP0INST_No (0x0UL)     /*!< Do not trace load instructions as P0 instructions.                   */
  #define ETM_TRCCONFIGR_LOADASP0INST_Yes (0x1UL)    /*!< Trace load instructions as P0 instructions.                          */

/* STOREASP0INST @Bit 2 : Instruction P0 field. This field controls whether store instructions are traced as P0 instructions. */
  #define ETM_TRCCONFIGR_STOREASP0INST_Pos (2UL)     /*!< Position of STOREASP0INST field.                                     */
