  #define ETM_TRCCONFIGR_COND_Min (0x0UL)            /*!< Min enumerator value of COND field.                                  */
  #define ETM_TRCCONFIGR_COND_Max (0x7UL)            /*!< Max enumerator value of COND field.                                  */
  #define ETM_TRCCONFIGR_COND_Disabled (0x0UL)       /*!< Conditional instruction tracing is disabled.                         */
