  #define ETM_TRCCONFIGR_RS_Min (0x0UL)              /*!< Min enumerator value of RS field.                                    */
  #define ETM_TRCCONFIGR_RS_Max (0x1UL)              /*!< Max enumerator value of RS field.                                    */
  #define ETM_TRCCONFIGR_RS_Disabled (0x0UL)         /*!< Return stack is disabled.                                            */
  #define ETM_TRCCONFIGR_RS_Enabled (0x1UL)          /*!< Return stack is enabled.                                             */

