/* DATAEN @Bit 4 : Data event enable bit. */
  #define ETM_TRCEVENTCTL1R_DATAEN_Pos (4UL)         /*!< Position of DATAEN field.                                            */
  #define ETM_TRCEVENTCTL1R_DATAEN_Msk (0x1UL << ETM_TRCEVENTCTL1R_DATAEN_Pos) /*!< Bit mask of DATAEN field.                  */
  #define ETM_TRCEVENTCTL1R_DATAEN_Min (0x0UL)       /*!< Min enumerator value of DATAEN field.                                */
  #define ETM_TRCEVENTCTL1R_DATAEN_Max (0x1UL)       /*!< Max enumerator value of DATAEN field.                                */
