  #define ETM_TRCQCTLR_RANGE7_Disabled (0x0UL)       /*!< Address range comparator 7 is disabled.                              */
  #define ETM_TRCQCTLR_RANGE7_Enabled (0x1UL)        /*!< Address range comparator 7 is selected for use.                      */

/* MODE @Bit 8 : Selects whether the address range comparators selected by the RANGE field indicate address ranges where the
                 trace unit is permitted to generate Q elements or address ranges where the trace unit is not permitted to
                 generate Q elements: */

  #define ETM_TRCQCTLR_MODE_Pos (8UL)                /*!< Position of MODE field.                                              */
  #define ETM_TRCQCTLR_MODE_Msk (0x1UL << ETM_TRCQCTLR_MODE_Pos) /*!< Bit mask of MODE field.                                  */
  #define ETM_TRCQCTLR_MODE_Min (0x0UL)              /*!< Min enumerator value of MODE field.                                  */
  #define ETM_TRCQCTLR_MODE_Max (0x1UL)              /*!< Max enumerator value of MODE field.                                  */
