  #define MIPIRFFE_RFFE_STATUS_STATUS_Msk (0xFUL << MIPIRFFE_RFFE_STATUS_STATUS_Pos) /*!< Bit mask of STATUS field.            */
  #define MIPIRFFE_RFFE_STATUS_STATUS_Min (0x0UL)    /*!< Min enumerator value of STATUS field.                                */
  #define MIPIRFFE_RFFE_STATUS_STATUS_Max (0xCUL)    /*!< Max enumerator value of STATUS field.                                */
  #define MIPIRFFE_RFFE_STATUS_STATUS_IDLE (0x0UL)   /*!< Rffe bus in idle state, clock and data driven actively low           */
  #define MIPIRFFE_RFFE_STATUS_STATUS_SSC1 (0x1UL)   /*!< Rffe bus in first start sequence cycle (data high, clock low)        */
  #define MIPIRFFE_RFFE_STATUS_STATUS_SSC0 (0x2UL)   /*!< Rffe bus in second start sequence cycle (data low, clock low)        */
  #define MIPIRFFE_RFFE_STATUS_STATUS_COMMAND_FRAME (0x3UL) /*!< Master is providing command frame to slave                    */
  #define MIPIRFFE_RFFE_STATUS_STATUS_COMMAND_PARITY (0x4UL) /*!< Master is providing command frame parity bit                 */
  #define MIPIRFFE_RFFE_STATUS_STATUS_WRITE_BYTE (0x5UL) /*!< Sdata and sclk driven by master                                  */
  #define MIPIRFFE_RFFE_STATUS_STATUS_WRITE_PARITY (0x6UL) /*!< Master is providing parity bit                                 */
