  #define MRAMC_TESTMODE2_MRAM_IN_RDEN_Pos (1UL)     /*!< Position of RDEN field.                                              */
  #define MRAMC_TESTMODE2_MRAM_IN_RDEN_Msk (0x1UL << MRAMC_TESTMODE2_MRAM_IN_RDEN_Pos) /*!< Bit mask of RDEN field.            */

/* NVR @Bit 2 : Select NVR pages/sectors */
  #define MRAMC_TESTMODE2_MRAM_IN_NVR_Pos (2UL)      /*!< Position of NVR field.                                               */
  #define MRAMC_TESTMODE2_MRAM_IN_NVR_Msk (0x1UL << MRAMC_TESTMODE2_MRAM_IN_NVR_Pos) /*!< Bit mask of NVR field.               */

/* CEb @Bit 3 : Chip Enable */
  #define MRAMC_TESTMODE2_MRAM_IN_CEb_Pos (3UL)      /*!< Position of CEb field.                                               */
  #define MRAMC_TESTMODE2_MRAM_IN_CEb_Msk (0x1UL << MRAMC_TESTMODE2_MRAM_IN_CEb_Pos) /*!< Bit mask of CEb field.               */

/* WEb @Bit 4 : Write Enable */
  #define MRAMC_TESTMODE2_MRAM_IN_WEb_Pos (4UL)      /*!< Position of WEb field.                                               */
  #define MRAMC_TESTMODE2_MRAM_IN_WEb_Msk (0x1UL << MRAMC_TESTMODE2_MRAM_IN_WEb_Pos) /*!< Bit mask of WEb field.               */

/* PROGEN @Bit 5 : Program Enable */
  #define MRAMC_TESTMODE2_MRAM_IN_PROGEN_Pos (5UL)   /*!< Position of PROGEN field.                                            */
  #define MRAMC_TESTMODE2_MRAM_IN_PROGEN_Msk (0x1UL << MRAMC_TESTMODE2_MRAM_IN_PROGEN_Pos) /*!< Bit mask of PROGEN field.      */

/* PROG @Bit 6 : Program signal */
  #define MRAMC_TESTMODE2_MRAM_IN_PROG_Pos (6UL)     /*!< Position of PROG field.                                              */
  #define MRAMC_TESTMODE2_MRAM_IN_PROG_Msk (0x1UL << MRAMC_TESTMODE2_MRAM_IN_PROG_Pos) /*!< Bit mask of PROG field.            */

/* ERASE @Bit 7 : Erase signal */
  #define MRAMC_TESTMODE2_MRAM_IN_ERASE_Pos (7UL)    /*!< Position of ERASE field.                                             */
  #define MRAMC_TESTMODE2_MRAM_IN_ERASE_Msk (0x1UL << MRAMC_TESTMODE2_MRAM_IN_ERASE_Pos) /*!< Bit mask of ERASE field.         */

/* SCE @Bit 8 : Sector Erase */
  #define MRAMC_TESTMODE2_MRAM_IN_SCE_Pos (8UL)      /*!< Position of SCE field.                                               */
  #define MRAMC_TESTMODE2_MRAM_IN_SCE_Msk (0x1UL << MRAMC_TESTMODE2_MRAM_IN_SCE_Pos) /*!< Bit mask of SCE field.               */

/* CHIP @Bit 9 : Chip Erase */
  #define MRAMC_TESTMODE2_MRAM_IN_CHIP_Pos (9UL)     /*!< Position of CHIP field.                                              */
  #define MRAMC_TESTMODE2_MRAM_IN_CHIP_Msk (0x1UL << MRAMC_TESTMODE2_MRAM_IN_CHIP_Pos) /*!< Bit mask of CHIP field.            */

/* PEON @Bit 10 : Read within program/erase */
  #define MRAMC_TESTMODE2_MRAM_IN_PEON_Pos (10UL)    /*!< Position of PEON field.                                              */
