/* SCLK @Bit 16 : Trim Configuration Clock */
  #define MRAMC_TESTMODE2_MRAM_IN_SCLK_Pos (16UL)    /*!< Position of SCLK field.                                              */
  #define MRAMC_TESTMODE2_MRAM_IN_SCLK_Msk (0x1UL << MRAMC_TESTMODE2_MRAM_IN_SCLK_Pos) /*!< Bit mask of SCLK field.            */

/* RETb @Bit 17 : Trim Configuration Register Retention (active low) */
