  #define MRAMC_READYNEXTTIMEOUT_DW_Pos (31UL)       /*!< Position of DW field.                                                */
  #define MRAMC_READYNEXTTIMEOUT_DW_Msk (0x1UL << MRAMC_READYNEXTTIMEOUT_DW_Pos) /*!< Bit mask of DW field.                    */
  #define MRAMC_READYNEXTTIMEOUT_DW_Min (0x0UL)      /*!< Min enumerator value of DW field.                                    */
