  #define NFCT_TXD_FRAMECONFIG_PARITY_Msk (0x1UL << NFCT_TXD_FRAMECONFIG_PARITY_Pos) /*!< Bit mask of PARITY field.            */
  #define NFCT_TXD_FRAMECONFIG_PARITY_Min (0x0UL)    /*!< Min enumerator value of PARITY field.                                */
  #define NFCT_TXD_FRAMECONFIG_PARITY_Max (0x1UL)    /*!< Max enumerator value of PARITY field.                                */
  #define NFCT_TXD_FRAMECONFIG_PARITY_NoParity (0x0UL) /*!< Parity is not added to TX frames                                   */
  #define NFCT_TXD_FRAMECONFIG_PARITY_Parity (0x1UL) /*!< Parity is added to TX frames                                         */

/* DISCARDMODE @Bit 1 : Discarding unused bits at start or end of a frame */
  #define NFCT_TXD_FRAMECONFIG_DISCARDMODE_Pos (1UL) /*!< Position of DISCARDMODE field.                                       */
  #define NFCT_TXD_FRAMECONFIG_DISCARDMODE_Msk (0x1UL << NFCT_TXD_FRAMECONFIG_DISCARDMODE_Pos) /*!< Bit mask of DISCARDMODE
                                                                            field.*/
  #define NFCT_TXD_FRAMECONFIG_DISCARDMODE_Min (0x0UL) /*!< Min enumerator value of DISCARDMODE field.                         */
  #define NFCT_TXD_FRAMECONFIG_DISCARDMODE_Max (0x1UL) /*!< Max enumerator value of DISCARDMODE field.                         */
  #define NFCT_TXD_FRAMECONFIG_DISCARDMODE_DiscardEnd (0x0UL) /*!< Unused bits are discarded at end of frame (EoF)             */
  #define NFCT_TXD_FRAMECONFIG_DISCARDMODE_DiscardStart (0x1UL) /*!< Unused bits are discarded at start of frame (SoF)         */

/* SOF @Bit 2 : Adding SoF or not in TX frames */
  #define NFCT_TXD_FRAMECONFIG_SOF_Pos (2UL)         /*!< Position of SOF field.                                               */
  #define NFCT_TXD_FRAMECONFIG_SOF_Msk (0x1UL << NFCT_TXD_FRAMECONFIG_SOF_Pos) /*!< Bit mask of SOF field.                     */
  #define NFCT_TXD_FRAMECONFIG_SOF_Min (0x0UL)       /*!< Min enumerator value of SOF field.                                   */
  #define NFCT_TXD_FRAMECONFIG_SOF_Max (0x1UL)       /*!< Max enumerator value of SOF field.                                   */
  #define NFCT_TXD_FRAMECONFIG_SOF_NoSoF (0x0UL)     /*!< SoF symbol not added                                                 */
  #define NFCT_TXD_FRAMECONFIG_SOF_SoF (0x1UL)       /*!< SoF symbol added                                                     */

/* CRCMODETX @Bit 4 : CRC mode for outgoing frames */
  #define NFCT_TXD_FRAMECONFIG_CRCMODETX_Pos (4UL)   /*!< Position of CRCMODETX field.                                         */
  #define NFCT_TXD_FRAMECONFIG_CRCMODETX_Msk (0x1UL << NFCT_TXD_FRAMECONFIG_CRCMODETX_Pos) /*!< Bit mask of CRCMODETX field.   */
  #define NFCT_TXD_FRAMECONFIG_CRCMODETX_Min (0x0UL) /*!< Min enumerator value of CRCMODETX field.                             */
  #define NFCT_TXD_FRAMECONFIG_CRCMODETX_Max (0x1UL) /*!< Max enumerator value of CRCMODETX field.                             */
  #define NFCT_TXD_FRAMECONFIG_CRCMODETX_NoCRCTX (0x0UL) /*!< CRC is not added to the frame                                    */
  #define NFCT_TXD_FRAMECONFIG_CRCMODETX_CRC16TX (0x1UL) /*!< 16 bit CRC added to the frame based on all the data read from RAM
                                                              that is used in the frame*/


/* NFCT_TXD_AMOUNT: Size of outgoing frame */
  #define NFCT_TXD_AMOUNT_ResetValue (0x00000000UL)  /*!< Reset value of AMOUNT register.                                      */

/* TXDATABITS @Bits 0..2 : Number of bits in the last or first byte read from RAM that shall be included in the frame (excluding
                           parity bit). */

  #define NFCT_TXD_AMOUNT_TXDATABITS_Pos (0UL)       /*!< Position of TXDATABITS field.                                        */
  #define NFCT_TXD_AMOUNT_TXDATABITS_Msk (0x7UL << NFCT_TXD_AMOUNT_TXDATABITS_Pos) /*!< Bit mask of TXDATABITS field.          */
  #define NFCT_TXD_AMOUNT_TXDATABITS_Min (0x0UL)     /*!< Min value of TXDATABITS field.                                       */
  #define NFCT_TXD_AMOUNT_TXDATABITS_Max (0x7UL)     /*!< Max size of TXDATABITS field.                                        */

/* TXDATABYTES @Bits 3..11 : Number of complete bytes that shall be included in the frame, excluding CRC, parity, and framing. */
  #define NFCT_TXD_AMOUNT_TXDATABYTES_Pos (3UL)      /*!< Position of TXDATABYTES field.                                       */
  #define NFCT_TXD_AMOUNT_TXDATABYTES_Msk (0x1FFUL << NFCT_TXD_AMOUNT_TXDATABYTES_Pos) /*!< Bit mask of TXDATABYTES field.     */
  #define NFCT_TXD_AMOUNT_TXDATABYTES_Min (0x000UL)  /*!< Min value of TXDATABYTES field.                                      */
  #define NFCT_TXD_AMOUNT_TXDATABYTES_Max (0x101UL)  /*!< Max size of TXDATABYTES field.                                       */



