  #define OTPC_TEST_LOCKTESTMODE_EnableLock_Min (0x0UL) /*!< Min enumerator value of EnableLock field.                         */
  #define OTPC_TEST_LOCKTESTMODE_EnableLock_Max (0x10CC10CCUL) /*!< Max enumerator value of EnableLock field.                  */
  #define OTPC_TEST_LOCKTESTMODE_EnableLock_LockDisabled (0x00000000UL) /*!< Read: TEST.TESTMODE is not locked.                */
  #define OTPC_TEST_LOCKTESTMODE_EnableLock_LockEnabled (0x00000001UL) /*!< Read: TEST.TESTMODE is locked.                     */
  #define OTPC_TEST_LOCKTESTMODE_EnableLock_EnableLock (0x10CC10CCUL) /*!< Write: Enables the lock (Ignores any other value
                                                                           written).*/



