  #define RICR_UROT_SMWD_SM_TBS_CIPHERDIGEST_VALUE_Msk (0xFFFFFFFFUL << RICR_UROT_SMWD_SM_TBS_CIPHERDIGEST_VALUE_Pos) /*!< Bit
                                                                            mask of VALUE field.*/
  #define RICR_UROT_SMWD_SM_TBS_CIPHERDIGEST_VALUE_Min (0xFFFFFFFFUL) /*!< Min enumerator value of VALUE field.                */
  #define RICR_UROT_SMWD_SM_TBS_CIPHERDIGEST_VALUE_Max (0xFFFFFFFFUL) /*!< Max enumerator value of VALUE field.                */
  #define RICR_UROT_SMWD_SM_TBS_CIPHERDIGEST_VALUE_Unprogrammed (0xFFFFFFFFUL) /*!< Encrypted firmware digest, unprogrammed if
                                                                            the FW is not programmed.*/


/* RICR_UROT_SMWD_SM_TBS_RFU: This register is included when generating signature of the TBS content of SM. */
  #define RICR_UROT_SMWD_SM_TBS_RFU_MaxCount (4UL)   /*!< Max size of RFU[4] array.                                            */
  #define RICR_UROT_SMWD_SM_TBS_RFU_MaxIndex (3UL)   /*!< Max index of RFU[4] array.                                           */
  #define RICR_UROT_SMWD_SM_TBS_RFU_MinIndex (0UL)   /*!< Min index of RFU[4] array.                                           */

/* RFU @Bits 0..31 : (unspecified) */
  #define RICR_UROT_SMWD_SM_TBS_RFU_RFU_Pos (0UL)    /*!< Position of RFU field.                                               */
  #define RICR_UROT_SMWD_SM_TBS_RFU_RFU_Msk (0xFFFFFFFFUL << RICR_UROT_SMWD_SM_TBS_RFU_RFU_Pos) /*!< Bit mask of RFU field.    */
  #define RICR_UROT_SMWD_SM_TBS_RFU_RFU_Min (0xFFFFFFFFUL) /*!< Min enumerator value of RFU field.                             */
  #define RICR_UROT_SMWD_SM_TBS_RFU_RFU_Max (0xFFFFFFFFUL) /*!< Max enumerator value of RFU field.                             */
  #define RICR_UROT_SMWD_SM_TBS_RFU_RFU_Unprogrammed (0xFFFFFFFFUL) /*!< The register is not programmed.                       */



