  #define SICR_UROT_UPDATE_STATUS_CODE_Min (0xF0000001UL) /*!< Min enumerator value of CODE field.                             */
  #define SICR_UROT_UPDATE_STATUS_CODE_Max (0xFFFFFFFFUL) /*!< Max enumerator value of CODE field.                             */
  #define SICR_UROT_UPDATE_STATUS_CODE_None (0xFFFFFFFFUL) /*!< No operation pending to indicate any status.                   */
  #define SICR_UROT_UPDATE_STATUS_CODE_UnknownOperation (0xF0000001UL) /*!< Unknown OPCODE in SICR.UROT.UPDATE.OPERATION.      */
